import { useState, useEffect } from 'react'
import type { ReactNode } from 'react'

import { useLocation } from 'react-router'
import { Box, HoverCard, HStack,　VStack, Icon, IconButton, Image, Portal, Text } from '@chakra-ui/react'

import { MyMenu } from './MyMenu'

import sheepicon from '/sheepicon.svg'

/** @jsxImportSource @emotion/react */
import { css, keyframes } from '@emotion/react'

type Prop = {
  children: ReactNode
}
export function MyHeader(prop: Prop) {
  const { children } = prop;
  const [ open, setOpen ] = useState<boolean>(false);
  const location = useLocation();
  
  const iconClickHandler = () => {
    setOpen(true);
  }
  
  useEffect(() => {
    const timingPhase01 = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--init-timing-phase-01'));
    const timer = setTimeout(() => {
        // hash付きの表示箇所指定でない(urlにhashが含まれない)場合、冒頭紹介をオープンする
        if (!location.hash) {
          setOpen(true);
        }
      }, timingPhase01);
    return () => clearTimeout(timer);
  }, []);
  
  // 冒頭紹介のHoverは、表示切り替えをマニュアルにして、初回起動時以外はIconクリック時のみ表示とする(hoverによる表示を無効化)
  return (
    <HoverCard.Root 
      open={open}
      openDelay={100} positioning={{ slide: true }}
      >
      <HStack as='header' gap='1' css={[header.style, header.loadingStyle]}>
        <HStack as='div' className='title-area'>
          <HoverCard.Trigger asChild>
            <IconButton css={header.iconArea.style} bg='none' aria-label='タイトルアイコン。クリックで冒頭紹介を開きます' onClick={iconClickHandler}>
              <Icon className='icon'>
                <Image src={sheepicon} loading='lazy' />
              </Icon>
            </IconButton>
          </HoverCard.Trigger>
          <Box as='h1' display='flex' alignItems='flex-end'>
            <Text fontFamily='Stick' fontSize={{ base: '2xl', md: '2xl', lg: '3xl' }} 
              fontWeight='900' 
              textShadow='0 0 1px red, 0 0 4px white'
              >
              がみ〜工房
            </Text>
            <Text fontFamily='Stick' fontSize={{ base: 'md', md: 'md', lg: 'lg' }} lineHeight={{ base: 1.0, md: 1.0, lg: 0.9 }} 
              fontWeight='bold' 
              textShadow='0 0 1px red, 0 0 4px white' 
              paddingLeft='3'
              >
              工作室
            </Text>
          </Box>
        </HStack>
        <Box flexGrow='1' />
        <Box h='100%' display='flex' alignItems='flex-end'>
          {children}
        </Box>
        <MyMenu />
      </HStack>
      <Portal>
        <IntroductionArea isOpen={open} closeMyself={() => setOpen(false)}/>
      </Portal>
    </HoverCard.Root>
  )
}


const headerKeyframes = {
  /* 閲覧者に近い位置から、画面上に像を結びながら着地するイメージ。translateZ()だとタイトルフォントが乱れたりいまいちな感じなのでscale()で実装 */
  fadeInShrink: keyframes`
    0% {
      opacity: 0;
      transform: scale(1.5);
    }
    50% {
      opacity: 0.7;
      transform: scale(1.3);
    }
    100% {
      opacity: 1;
      transform: scale(1.0);
    }
  `
} as const
const header = {
  style: css`
    width: 100%;
    /* headerの高さは、flexの自動調整の対象外にし、ただ--header-heightの値とする */
    height: var(--header-height);
    flex-grow: 0;
    flex-shrink: 0;
    
    z-index: 1;
    box-shadow: 1px 1px 2px rgb(0 0 0 / 0.25);
    
    padding-left: 0.25rem; padding-right: 0.25rem;
    background-image: url('${import.meta.env.BASE_URL}/substrate_h.jpg');
    background-repeat: repeat repeat;
    /* 背景画像が読み込まれるまでの表示のため、背景を画像のメイン色で塗りつぶす */
    background-color: rgb(228 180 114);
    
    .title-area {
      background-image: url('${import.meta.env.BASE_URL}/substrate_h.jpg');
      background-repeat: repeat repeat;
      height: calc(100% - (1px * 2));
      margin-top: 1px;
      border-radius: 0.5rem;
      box-shadow: -1px -1px 1px rgb(255 255 255 / 0.4), 1px 1px 2px rgb(0 0 0 / 0.25);
      padding-left: 0.25rem; padding-right: 1rem;
    }
  `,
  loadingStyle: css`
    opacity: 0;
    transform: scale(1.2);
    animation: ${headerKeyframes.fadeInShrink} calc(var(--init-timing-phase-01) * 1ms) ease-out forwards;
  `,
  iconArea: {
    style: css`
      position: relative;
      
      &::before {
        content: '';
        position: absolute;
        inset: 0;
        background: rgb(0 0 0 / 0.5);
        clip-path: circle(1em);
      }
      > .icon {
        width: 2.5rem;
        height: 2.5rem;
        filter: drop-shadow(1px 1px 2px rgba(150, 50, 50, 0.8)) drop-shadow(1px 3px 8px rgba(100, 100, 100, 0.5));
        
        transform: scale(1);
        opacity: 1;
        transition: opacity 0.5s ease, transform 1s cubic-bezier(0.3, 0.2, 0.8, 1.8);
        @starting-style {
          transform: scale(0.2);
          opacity: 0.1;
        }
      }
    `
  }
} as const




import { lazy, useRef, Suspense } from 'react'
import { Skeleton } from '@chakra-ui/react'
import { MyScrollArea, useMyScrollArea } from '~/ui/parts/MyScrollArea'
import { MyCloseButton } from '~/ui/parts/MyButton'

const MyIntroduction = lazy(() => import('./MyIntroduction'));

type IntroductionAreaProp = {
  isOpen: boolean;
  closeMyself: () => void;
}
function IntroductionArea(prop: IntroductionAreaProp) {
  const { isOpen, closeMyself } = prop;
  
  const scrollArea = useMyScrollArea();
  const [isCursolDrag, setIsCursolDrag] = useState<boolean>(false);
  
  useEffect(() => {
    scrollArea.scrollToEdge({ edge: 'top' });
    setIsCursolDrag(false);
  }, [isOpen]);
  
  const introductionRef = useRef<HTMLDivElement | null>(null);
  const bottomRef = useRef<HTMLDivElement | null>(null);
  
  useEffect(() => {
    if (introductionRef.current && bottomRef.current) {
      const handler = (event: MouseEvent) => {
        if (!introductionRef.current || !bottomRef.current) return;
        
        if (event.type === 'mousedown' && event.target instanceof HTMLElement && 
            event.target.classList.contains('scroll-thumb')) {
          setIsCursolDrag(true);
        }
        if (event.type === 'mouseup') {
          setIsCursolDrag(false);
        }
      }
      introductionRef.current.addEventListener('mousedown', handler, {passive: true});
      introductionRef.current.addEventListener('mouseup', handler, {passive: true});
      return () => {
        introductionRef.current?.removeEventListener('mousedown', handler);
        introductionRef.current?.removeEventListener('mouseup', handler);
      };
    }
  }, []);
  useEffect(() => {
    if (introductionRef.current && bottomRef.current) {
      /***
      純粋なJSを使った場合の処理。Chakra UIだとuseMyScrollArea()でisAtBottomが得られるのでそちらを使う。
      ただ、状態が変わる毎にuseMyScrollArea()は再生成されちゃうので、Eventハンドラも毎回更新する。
      const before = { y: 0 };
      const handler = (event: WheelEvent | TouchEvent) => {
        if (!introductionRef.current || !bottomRef.current) return;
        
        const areaY = introductionRef.current.getBoundingClientRect().bottom;
        const y = bottomRef.current.getBoundingClientRect().top;
        if ((event instanceof WheelEvent && event.deltaY > 0 && areaY > y)
          || (event instanceof TouchEvent && areaY > y && before.y == y)) {
          closeMyself();
          event.stopPropagation();
          if(event.cancelable) {
            event.preventDefault();
          }
        }
        before.y = y;
      }
       ***/
      const handler = (event: WheelEvent | TouchEvent | MouseEvent) => {
        if (!introductionRef.current || !bottomRef.current) return;
        if (event?.constructor ===  MouseEvent && !isCursolDrag) return;
        
        // 以下は考慮できていない。
        // ・TouchEventでBottom到着後、上へスクロールしたか下へスクロールしたかの判断
        if ((event instanceof WheelEvent && scrollArea.isAtBottom && event.deltaY > 0)
          || (typeof TouchEvent !== 'undefined' && event instanceof TouchEvent && scrollArea.isAtBottom)
          || (event instanceof MouseEvent && scrollArea.isAtBottom && isCursolDrag && event.movementY > 0)) {
          closeMyself();
          event.stopPropagation();
          if(event.cancelable) {
            event.preventDefault();
          }
        }
      }
      introductionRef.current.addEventListener('wheel', handler, {passive: false});
      introductionRef.current.addEventListener('touchmove', handler, {passive: false});
      introductionRef.current.addEventListener('mousemove', handler, {passive: false});
      return () => {
        introductionRef.current?.removeEventListener('wheel', handler);
        introductionRef.current?.removeEventListener('touchmove', handler);
        introductionRef.current?.removeEventListener('mousemove', handler);
      };
    }
  }, [scrollArea, isCursolDrag]);
  
  return (
    <HoverCard.Positioner msmDown={{ '--header-padding-inline': '0.5em' }}>
      <HoverCard.Content 
        ref={introductionRef} css={introduction.content}
        w='calc(100svw - (var(--body-margin) + var(--x)) * 2)' 
        minW='calc(100svw - (var(--body-margin) + var(--x)) * 2)' 
        maxHeight='calc(95svh - 3rem)'
      　>
        <HoverCard.Arrow />
        <MyCloseButton className='close-button' onClick={closeMyself} />
        <Text className='hello' fontSize={{ base: '2xl', md: '2xl', lg: '3xl' }}>
          <span>ー&nbsp;</span><span>こ</span><span>ん</span><span>に</span><span>ち</span><span>は</span><span>ー</span>
        </Text>
        <MyScrollArea.Provider scrollArea={scrollArea}>
          <VStack>
            <Suspense fallback={<Skeleton w='100%' h='120lvh' />}>
              <MyIntroduction />
            </Suspense>
            <div ref={bottomRef}></div>
          </VStack>
        </MyScrollArea.Provider>
      </HoverCard.Content>
    </HoverCard.Positioner>
  )
}


const introductionKeyframes = {
  slideFromTop: keyframes`
    0% {
      transform: translate(0, -50rem);
    }
    100% {
      transform: translate(0);
    }
  `,
  slideToTop: keyframes`
    0% {
      transform: translate(0);
    }
    100% {
      transform: translate(0, -1rem);
    }
  `
} as const
const introduction = {
  content: css`
    position: relative;
    
    // 吹き出しの三角部分と本体部分の背景色
    --hovercard-bg: rgb(230 230 255);
    background: radial-gradient(circle at 50% calc(5lh + min(15em, 40svh, 40svw) / 2), white 0, rgb(250 250 255) min(15em, 40svh, 40svw), rgb(230 230 255) calc(min(15em, 40svh, 40svw) + 10em));
    
    padding-inline: var(--header-padding-inline, revert-rule);
    
    // 閉じるときのアニメーション
    &:is([closed], [data-closed], [data-state=closed])[data-placement^=bottom] {
      animation-name: ${introductionKeyframes.slideToTop}, fade-out;
      animation-duration: 100ms;
    }
    // 開くときのアニメーション
    &:is([open], [data-open], [data-state=open])[data-placement^=bottom] {
      animation-name: ${introductionKeyframes.slideFromTop}, fade-in;
      animation-duration: 1s;
    }
    > .close-button {
      position: absolute;
      top: 0.5em;
      right: 1em;
      height: 2em;
      width: 2em;
      min-width: unset;
      padding-inline: unset;
    }
    
    > .hello {
      position: relative;
      height: 5lh;
      margin: 0.25em auto;
      font-family: Stick;
      font-weight: 900;
      text-shadow: 0 0 1px red;
      
      > span {
        position: absolute;
        top: 0;
        left: calc(50% - 0.5em);
        transform-origin: center 15lh;
      }
      > span:nth-of-type(n) {
        transform: rotate(calc(6deg * (var(--number) - 4)));
      }
      > span:first-of-type, span:last-of-type {
        font-size: 0.5em;
      }
      > span:nth-of-type(1) { --number: 1; }
      > span:nth-of-type(2) { --number: 2; }
      > span:nth-of-type(3) { --number: 3; }
      > span:nth-of-type(4) { --number: 4; }
      > span:nth-of-type(5) { --number: 5; }
      > span:nth-of-type(6) { --number: 6; }
      > span:nth-of-type(7) { --number: 7; }
    }
  `
} as const


