import { useState, useEffect } from 'react'
import type { ReactNode } from 'react'

import { useNavigate, useLocation } from 'react-router'
import { Box, Text, Tabs, Icon, useBreakpointValue } from '@chakra-ui/react'
import type { MenuValueChangeDetails, TabsTriggerProps } from '@chakra-ui/react'

import { paths } from '~/paths'
import { useRippleEffect, RippleEffect } from '~/ui/parts/effect/RippleEffect'

import blockSmall from './icon/block_small.svg'
import blockLarge from './icon/block_large.svg'
import beadsSmall from './icon/beads_small.svg'
import beadsLarge from './icon/beads_large.svg'



/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


export default function MyNavi() {
  const navigate = useNavigate();
  const location = useLocation();
  
  const [ curTabValue, setCurTabValue ] = useState<string>('');
  const onValueChange = ({ value }: MenuValueChangeDetails) => {
    setCurTabValue(value);
    navigate(`/${value}`);
  };
  useEffect(() => {
    const targetTabValue = location.pathname.split('/')[1];
    if (targetTabValue && targetTabValue != curTabValue) {
      setCurTabValue(targetTabValue);
    }
  }, [location]);
  
  const tabResp = useBreakpointValue<typeof tabs.base | typeof tabs.lg>({ lgDown: tabs.base, lg: tabs.lg }, { ssr: false }) || tabs.base;
  
  return (
    <Tabs.Root 
      onValueChange={onValueChange} 
      value={curTabValue} 
      fitted={{ msmDown: true, msm: false }}
      orientation={tabResp.listOrientation}
      variant='plain'
      lazyMount={true}
      unmountOnExit={true}
      >
      <Tabs.List gap='1px'>
        {[
          { value: paths.block.key, srcSm: blockSmall, srcLg: blockLarge, title: 'ブロック', subTitle: (<>LEGOやLaQなどのブロック系工作</>) },
          { value: paths.beads.key, srcSm: beadsSmall, srcLg: beadsLarge, title: 'ビーズ', subTitle: (<>アイロンビーズなどのビーズ3D工作</>) },
        ].map((info, index) => (
          <MyTabTrigger 
            key={info.value}
            value={info.value}
            tabIndex={index}
            css={[tabs.styles.button, tabResp.button.style]}
            >
            <Box css={[tabs.styles.iconArea, tabResp.iconArea.style]}>
              <Icon className='icon'>
                <Box as='div' 
                  maskImage={`url("${(tabResp.listOrientation == 'horizontal') ? info.srcSm : info.srcLg}")`} 
                  maskMode='alpha' maskSize='100% auto' maskRepeat='no-repeat' />
              </Icon>
            </Box>
            <Box as={info.value === curTabValue ? 'h3' : 'div'} css={tabResp.title.style}>
              <Text as='span' className='title'>{info.title}</Text>
              <Text as='span' className='sub-title' hideBelow='lg'>{info.subTitle}</Text>
            </Box>
          </MyTabTrigger>
        ))}
        <Tabs.Indicator css={tabs.styles.indicator} 
          msmDown={{ roundedTop: 'unset', roundedBottom: 'l2' }}
          msm={{ roundedTop: 'l2', roundedBottom: 'unset' }}
          lg={{ roundedLeft: 'l2', roundedRight: 'unset' }}
          />
      </Tabs.List>
    </Tabs.Root>
  )
}


type MyTabTriggerProp = TabsTriggerProps & {
  children: ReactNode;
}
function MyTabTrigger(prop: MyTabTriggerProp) {
  const { children, ...otherProp } = prop;
  const { targetProp, effectProp } = useRippleEffect<HTMLButtonElement>();
  
  return (
    <Tabs.Trigger {...otherProp} {...targetProp}>
      {children}
      <RippleEffect marginLeft='calc(var(--chakra-spacing-2) * -1)' {...effectProp} />
    </Tabs.Trigger>
  )
}


const tabs = {
  styles: {
    button: css`
      border-top: 2px solid rgb(100 100 100 / 0.5);
      border-left: 2px solid rgb(100 100 100 / 0.5);
      border-right: 1px solid rgb(255 200 200 / 0.5);
      border-bottom: 1px solid rgb(255 200 200 / 0.5);
      background: rgb(90 30 30 / 0.3);
      color: rgb(90 30 30);
      text-shadow: 0 0 1px goldenrod;
      
      &:is([aria-selected=true], [data-selected]) {
        border-color: transparent;
        box-shadow: -1px -1px 2px rgb(255 200 200 / 9);
        background: transparent;
        color: rgb(30 30 30);
        text-shadow: 0 0 1px sandybrown;
      }
      @media (hover: hover) {
        &:not(:is([aria-selected=true], [data-selected])):hover {
          border-color: transparent;
          filter: invert(40%);
        }
      }
      &:active {
        border-color: transparent;
        background: rgb(90 30 30 / 0.4);
      }
    `,
    iconArea: css`
      aspect-ratio: 1 / 1;
      
      .icon {
        aspect-ratio: 1 / 1;
        background: rgb(120 60 60 / 1);
        filter: drop-shadow(10px 10px 5px rgb(90 90 30 / 0.5));
        
        *:is([aria-selected=true], [data-selected]) > & {
          background: rgb(200 50 50);
        }
        
        transition: all 1s cubic-bezier(0.3, 0.2, 0.8, 1.8);
      }
    `,
    indicator: css`
      background: rgb(255 255 255 / 0.7);
    `
  },
  base: {
    listOrientation: 'horizontal',
    button: {
      style: css`
        aspect-ratio: 3 / 2;
        position: relative;
        padding-block: unset;
        padding-inline: unset;
      `
    },
    iconArea: {
      style: css`
        width: var(--chakra-sizes-8);
        margin: 0 auto;
        
        .icon {
          width: var(--chakra-sizes-7);
          *:is([aria-selected=true], [data-selected]) > & {
            width: var(--chakra-sizes-8);
          }
        }
      `
    },
    title: {
      style: css`
        position: absolute;
        bottom: 0;
        width: 100%;
        .title {
          font-size: 0.7rem;
        }
      `
    }
  },
  lg: {
    listOrientation: 'vertical',
    button: {
      style: css`
        height: 5rem;
        width: 14rem;
        justify-content: left; 
      `
    },
    iconArea: {
      style: css`
        width: var(--chakra-sizes-10);
        
        .icon {
          width: var(--chakra-sizes-9);
          *:is([aria-selected=true], [data-selected]) > & {
            width: var(--chakra-sizes-10);
          }
        }
      `
    },
    title: {
      style: css`
        display: flex;
        flex-direction: column;
        .title {
          word-break: keep-all;
          text-align: left;
          font-size: 1rem;
        }
        .sub-title {
          text-align: left;
          font-size: 0.5rem;
        }
      `
    }
  },
} as const

