import { Suspense, useEffect } from 'react'
import { Outlet, useNavigate, useSearchParams } from 'react-router'
import { Box, HStack, Skeleton } from '@chakra-ui/react'

import { MyHeader } from '~/ui/layout/MyHeader'
import MyNavi from '~/ui/layout/MyNavi'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'

export default function RootArea() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  
  useEffect(() => {
    // 404.html からの redirect であれば、元々指定されたpathへ遷移する
    if (searchParams?.get('path')?.includes(import.meta.env.BASE_URL)) {
      const redirectUrl = searchParams?.get('path')?.split('/').slice(2).join('/');
      const hash = searchParams?.get('hash');
      if (redirectUrl) {
        navigate({ pathname:`/${redirectUrl}`, hash: hash ? `#${hash}` : undefined });
      }
    }
  }, []);
  
  return (
    <>
      <MyHeader>
        <Box as='nav' hideFrom='lg' hideBelow='msm'>
          <MyNavi />
        </Box>
      </MyHeader>
      <HStack flexGrow='1' w='100%' minH='0' gap='1px'>
        <Box as='nav' hideBelow='lg' css={styles.sideNavi}>
          <Box h='0.25em' bg='rgb(0 0 0 / 0.2)' />
          <Box display='flex' flexDirection='row'>
            <Box w='0.4em' bg='rgb(0 0 0 / 0.1)' />
            <MyNavi />
          </Box>
          <Box flexGrow='1' bg='rgb(0 0 0 / 0.1)' />
        </Box>
        <Box as='main' flexGrow='1' overflow='auto' h='100%'>
          <Suspense fallback={<MainAreaSuspense />}>
            <Box maxHeight='100%' h='100%' bg='var(--bg, #fff)'>
              <Outlet />
            </Box>
          </Suspense>
        </Box>
      </HStack>
      <Box as='footer'>
        <Box as='nav' hideFrom='msm' h='var(--footer-height)' css={styles.bottomNavi}>
          <MyNavi />
        </Box>
      </Box>
    </>
  )
}

function MainAreaSuspense() {
  return (
    <>
      <style>{`
        .main-suspense-area {
          width: 100%;
          height: 100%;
          background: var(--bg, #fff);
          opacity: 1;
          
          transition: opacity 4s ease;
          
          @starting-style {
            opacity: 0;
          }
        }
      `}</style>
      <Box className='main-suspense-area'>
        <Skeleton w='100%' h='100%' />
      </Box>
    </>
  )
}

const styles = {
  sideNavi: css`
    display: flex;
    flex-direction: column;
    height: 100%;
    background-image: url('${import.meta.env.BASE_URL}/substrate_v.jpg');
    background-repeat: repeat repeat;
    /* 背景画像が読み込まれるまでの表示のため、背景を画像のメイン色で塗りつぶす */
    background-color: rgb(228 180 114);
    
    transition: opacity 2s 1s, transform 1.5s 1s;
    
    @starting-style {
      opacity: 0;
      transform: translateX(-5rem);
    }
  `,
  bottomNavi: css`
    background-image: url('${import.meta.env.BASE_URL}/substrate_h.jpg');
    background-repeat: repeat repeat;
    /* 背景画像が読み込まれるまでの表示のため、背景を画像のメイン色で塗りつぶす */
    background-color: rgb(228 180 114);
    
    transition: opacity 2s 1s, transform 1.5s 1s;
    
    @starting-style {
      opacity: 0;
      transform: translateY(3rem);
    }
  `
}
